public final class CustomProjectLayout extends org.machanism.machai.project.layout.ProjectLayout {
    public java.util.Collection<java.lang.String> getSources() { return java.util.Collections.singletonList("custom/src"); }
    public java.util.Collection<java.lang.String> getDocuments() { return java.util.Collections.singletonList("custom/docs"); }
    public java.util.Collection<java.lang.String> getTests() { return java.util.Collections.singletonList("custom/test"); }
}

